//! Shape (b) closure: populates `data.raw_tokens` on every `data/corpus/*/class/*.json`
//! record that does not carry it yet.
//!
//! SD-32 T12 row 21 confirmed the gap (`kanban.md` row 21, retro dedupe-key
//! `row21-shape-b-class-raw-tokens-not-fixed`): 27 of 168 `class` records -- the `core_rulebook`,
//! `advanced_class_guide` and `advanced_players_guide` base-class chassis records generated by
//! `gen_core_rulebook_cache.rs::class_cache_data` / `cache_gen::acg::generate_classes` /
//! `cache_gen::apg`'s equivalent -- carry `data.class_id`/`maxlevel`/`bab`/`save_fort`/`save_ref`/
//! `save_will` (numeric formulas the compiled Rust `class_tables` module already knows) but no
//! `raw_tokens` field at all: a DIFFERENT generator/schema than `class_feature`'s (which does
//! carry `raw_tokens`), so row 21's `class_feature.rs`/`WiringClassIndex::closure_rows` fix never
//! touched these records, and logged the gap as a deferral rather than fixing it (`§27b` does not
//! accept an inherited deferral as a disposition -- this file is the fix).
//!
//! **Same posture as `enrich_equipment_raw_tokens.rs`/`enrich_spell_raw_tokens.rs`: an additive
//! enrichment pass over EXISTING on-disk JSON, never a second generator.** Every one of these 27
//! records already carries a real `source.kind: "lst_token"` citation (`source.path` +
//! `source.line` + `source.record_key`, e.g. `CLASS:Fighter`) -- this tool re-reads that exact
//! cited line, plus (row 21's own finding: a `.MOD`-appended line targeting the same identity can
//! live on a separate row) the record's full `.MOD`/`.COPY=` closure via
//! [`codex::rules_core::cache_gen::WiringClassIndex::closure_rows_for_book`] -- the IDENTICAL
//! closure machinery row 21 already proved safe for `class_feature`, reused here rather than a
//! fourth mechanism (`decisions.md §17`). Operates on raw `serde_json::Value` and only ever
//! inserts the one new `raw_tokens` key, so every other field (`class_id`, `bab`, `save_fort`,
//! ...) survives untouched by construction, regardless of book-specific schema shape --
//! `enrich_equipment_raw_tokens.rs`'s own module doc names the exact data-loss failure mode a
//! typed re-serialize risks, and this tool avoids it the same way.
//!
//! A record is left untouched (not an error) when: it already carries `raw_tokens` (idempotent --
//! safe to re-run); its `source.kind` is not `lst_token` (no raw `.lst` line to enrich from); or
//! its own cited row (or `.MOD`/`.COPY=` closure) declares `NAMEISPI:YES` (a name cannot be
//! redacted, `decisions.md §50.3` -- mirrors `enrich_equipment_raw_tokens.rs`'s identical refusal).

use std::env;
use std::fs;
use std::path::{Path, PathBuf};

use codex::rules_core::cache_gen::WiringClassIndex;
use codex::rules_core::corpus_literal_sweep::tab_tokens;
use codex::rules_core::pi_screening::{classify_field, declared_product_identity, DeclaredProductIdentity};
use codex::rules_core::shape_b_v1::{License, REDACTED_PI_MARKER};
use serde_json::{json, Value};

fn pcgen_data_root() -> PathBuf {
    if let Ok(v) = env::var("PCGEN_CORPUS_ROOT") {
        return PathBuf::from(v);
    }
    if let Ok(v) = env::var("PCGEN_DATA_ROOT") {
        return PathBuf::from(v);
    }
    let home = env::var("HOME").expect("HOME must be set to locate the default PCGen corpus checkout");
    PathBuf::from(home).join("workspace/repos/pcgen/data")
}

fn find_class_json_files(corpus_root: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    let Ok(books) = fs::read_dir(corpus_root) else { return out };
    for book_entry in books.flatten() {
        let class_dir = book_entry.path().join("class");
        if !class_dir.is_dir() {
            continue;
        }
        let Ok(entries) = fs::read_dir(&class_dir) else { continue };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) == Some("json") {
                out.push(path);
            }
        }
    }
    out
}

/// `NAMEISPI:`/`DESCISPI:` read straight off one raw `.lst` row's own tab-separated fields --
/// mirrors `enrich_equipment_raw_tokens.rs::declared_pi_on_line` exactly, reproduced locally per
/// this package's disjoint-file-touch convention for enrichment tools.
fn declared_pi_on_line(line_text: &str) -> DeclaredProductIdentity {
    let tokens: Vec<(&str, &str)> = line_text.split('\t').filter_map(|field| field.split_once(':')).collect();
    declared_product_identity(tokens)
}

/// PI-screens one raw token value before it ships -- the same union contract
/// (`enrich_equipment_raw_tokens.rs::screen_field_value`, `enrich_monster_ability_raw_tokens.rs`'s
/// function of the same name) every sibling enrichment tool applies: a declared `DESCISPI:YES`
/// covering `DESC`-keyed fields, unioned with a blacklist-term scan over every field regardless of
/// key.
fn screen_field_value(key: &str, value: &str, declared_description: bool) -> String {
    if key.eq_ignore_ascii_case("DESC") && declared_description {
        return REDACTED_PI_MARKER.to_string();
    }
    let (license, ..) = classify_field(key, value);
    if license == License::PiRedacted {
        return REDACTED_PI_MARKER.to_string();
    }
    value.to_string()
}

enum Outcome {
    Enriched(usize),
    AlreadyEnriched,
    NoLstCitation,
    CitationMiss(String),
    DroppedPi(String),
}

fn enrich_one(path: &Path, data_root: &Path) -> Outcome {
    let text = fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path:?}: {e}"));
    let mut root: Value = serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse {path:?} as JSON: {e}"));

    {
        let data = root.get("data").unwrap_or_else(|| panic!("{path:?}: no top-level \"data\" object"));
        if data.get("raw_tokens").is_some() {
            return Outcome::AlreadyEnriched;
        }
    }

    let source = root["source"].clone();
    if source.get("kind").and_then(Value::as_str) != Some("lst_token") {
        return Outcome::NoLstCitation;
    }
    let lst_rel_path = source["path"].as_str().expect("lst_token source must carry a path").to_string();
    let line = source["line"].as_u64().expect("lst_token source must carry a line");
    let record_key = source.get("record_key").and_then(Value::as_str).unwrap_or("<unknown>").to_string();

    let lst_full_path = data_root.join(&lst_rel_path);
    if !lst_full_path.is_file() {
        return Outcome::CitationMiss(format!("cited LST file not found: {lst_full_path:?}"));
    }

    // The book directory `WiringClassIndex` needs is the cited `.lst`'s own parent directory --
    // every one of these books' `book_dir()` helper (`cache_gen::acg`/`apg`, and
    // `gen_core_rulebook_cache.rs`'s own corpus root) already IS that same directory, so deriving
    // it from `source.path` here is book-agnostic by construction rather than a third hardcoded
    // per-book table.
    let lst_rel = Path::new(&lst_rel_path);
    let book_dir_rel = lst_rel.parent().unwrap_or(Path::new(""));
    let book_dir = data_root.join(book_dir_rel);
    let lst_basename = lst_rel.file_name().and_then(|n| n.to_str()).unwrap_or(&lst_rel_path);
    // `book_id` is only ever used as this index's own internal map key -- a single-book index
    // never needs it to match any OTHER identifier, so the book directory's own path string is a
    // fine, always-unique choice.
    let book_id = book_dir.to_string_lossy().to_string();
    let wiring_index = WiringClassIndex::build(&book_id, &book_dir);
    let mut lines = wiring_index.lines();

    // Row 21's own closure machinery, reused verbatim (`decisions.md §17`): the cited base row,
    // plus every `.MOD` row this book's `.lst` files carry against the SAME identity
    // (`record_key`, e.g. `CLASS:Fighter` -- a class record's identity column IS its own
    // `record_key`, confirmed live against every one of the 27 cited rows, so `name`/`key` are
    // the same string here), plus a `.COPY=` base row when applicable.
    let closure_rows = wiring_index.closure_rows(&mut lines, lst_basename, line as u32, &record_key, &record_key);
    let Some(Some(base_row)) = closure_rows.first() else {
        return Outcome::CitationMiss(format!(
            "{lst_rel_path}:{line} (record_key={record_key:?}): no row at the cited line"
        ));
    };
    // Defense in depth, mirroring `enrich_equipment_raw_tokens.rs`'s identical byte-present
    // check: the base row this closure returns must actually BE the cited line's own text.
    let cited_line_text = fs::read_to_string(&lst_full_path)
        .unwrap_or_default()
        .lines()
        .nth((line as usize).saturating_sub(1))
        .unwrap_or("")
        .to_string();
    if base_row != &cited_line_text {
        return Outcome::CitationMiss(format!(
            "{lst_rel_path}:{line} (record_key={record_key:?}): closure's base row does not match \
             the cited line's own text -- refusing to ship an unprovable citation"
        ));
    }

    // PI screen, over the whole closure (every row `closure_rows` returned, base + any `.MOD`/
    // `.COPY=` rows) -- SD-30 `§52.3`/`§53.5` union, mirrors every sibling enrichment tool's
    // identical closure-wide read. A name cannot be redacted (`decisions.md §50.3`): drop the
    // whole enrichment rather than ship a byte-identical `raw_tokens` array for a record whose
    // name the generator already excluded.
    let mut declared_name = false;
    let mut declared_description = false;
    for row in closure_rows.iter().flatten() {
        let d = declared_pi_on_line(row);
        declared_name = declared_name || d.name;
        declared_description = declared_description || d.description;
    }
    if declared_name {
        return Outcome::DroppedPi(format!(
            "{lst_rel_path}:{line} (record_key={record_key:?}) declares NAMEISPI:YES in its own \
             closure -- a name cannot be redacted, refusing to write raw_tokens for it"
        ));
    }

    // One raw row's own tab-delimited tokens as `{key, value}` pairs, field 0 (the identity
    // column) skipped -- mirrors `class_feature.rs::row_tokens`/`corpus_literal_sweep::tab_tokens`
    // exactly, screened through the same union scan every sibling enrichment tool applies.
    let mut raw_tokens: Vec<Value> = Vec::new();
    for row in closure_rows.iter().flatten() {
        for field in tab_tokens(row) {
            let Some((key, value)) = field.split_once(':') else { continue };
            let stored = screen_field_value(key, value, declared_description);
            raw_tokens.push(json!({ "key": key, "value": stored }));
        }
    }
    let written_count = raw_tokens.len();

    let data_obj =
        root.get_mut("data").and_then(Value::as_object_mut).expect("\"data\" must be a JSON object");
    data_obj.insert("raw_tokens".to_string(), Value::Array(raw_tokens));

    let new_json = serde_json::to_string_pretty(&root).expect("serialize enriched record");
    fs::write(path, new_json + "\n").unwrap_or_else(|e| panic!("write {path:?}: {e}"));
    Outcome::Enriched(written_count)
}

fn main() {
    let data_root = pcgen_data_root();
    let corpus_root = PathBuf::from("data/corpus");
    let files = find_class_json_files(&corpus_root);

    let mut total_enriched = 0u32;
    let mut total_already = 0u32;
    let mut total_no_citation = 0u32;
    let mut total_dropped_pi = 0u32;
    let mut misses: Vec<String> = Vec::new();
    let mut dropped_pi: Vec<String> = Vec::new();

    for file in &files {
        match enrich_one(file, &data_root) {
            Outcome::Enriched(n) => {
                total_enriched += 1;
                eprintln!("{}: enriched, {n} raw_tokens", file.display());
            }
            Outcome::AlreadyEnriched => total_already += 1,
            Outcome::NoLstCitation => total_no_citation += 1,
            Outcome::CitationMiss(msg) => misses.push(format!("{}: {}", file.display(), msg)),
            Outcome::DroppedPi(msg) => {
                total_dropped_pi += 1;
                dropped_pi.push(format!("{}: {}", file.display(), msg));
            }
        }
    }

    eprintln!(
        "\nenrich_class_raw_tokens: {} class files scanned, {total_enriched} enriched, \
         {total_already} already-enriched, {total_no_citation} no-LST-citation (untouched), \
         {total_dropped_pi} skipped (declared NAMEISPI:YES), {} citation misses",
        files.len(),
        misses.len()
    );
    if !misses.is_empty() {
        eprintln!("\nCitation misses (not enriched, real gaps to investigate):");
        for miss in &misses {
            eprintln!("  {miss}");
        }
    }
    if !dropped_pi.is_empty() {
        eprintln!("\nSkipped for declared Product Identity (raw_tokens NOT written for these):");
        for d in &dropped_pi {
            eprintln!("  {d}");
        }
    }
}
